import { expect, test } from 'bun:test';
import { convertBangumiSubject, convertProviderRecord, ProviderConversionError } from './packages/conversion/src/index.ts';

const identity = { key: 'caller-coordinate', provider: 'vndb', namespace: 'vn', externalId: 'v11' };
const data = { id: 'v11', name: 'Exact', olang: 'ja' };

test('declared VNDB namespaces convert and unrelated unsupported input is refused', () => {
  for (const [namespace, native] of Object.entries({ vn: 'work', release: 'release', character: 'character', staff: 'person', producer: 'organization', tag: 'concept', trait: 'concept' })) {
    expect(convertProviderRecord({ ...identity, namespace }, data).native).toBe(native);
  }
  for (const namespace of ['', 'not-a-kind']) {
    expect(() => convertProviderRecord({ ...identity, namespace }, data)).toThrow(ProviderConversionError);
  }
  expect(() => convertProviderRecord({ ...identity, provider: 'not-a-provider' }, data)).toThrow(ProviderConversionError);
});

for (const namespace of ['constructor', '__proto__', 'toString']) {
  test(`unsupported VNDB namespace ${namespace} is refused instead of yielding a nonstring native kind`, () => {
    let converted: ReturnType<typeof convertProviderRecord> | undefined;
    let error: unknown;
    try { converted = convertProviderRecord({ ...identity, namespace }, data); } catch (caught) { error = caught; }
    console.info('unsupported namespace result', JSON.stringify({ namespace, nativeType: typeof converted?.native, serialized: converted, errorBasis: error instanceof ProviderConversionError ? error.basis : null }));
    expect(error).toBeInstanceOf(ProviderConversionError);
    if (error instanceof ProviderConversionError) expect(error.basis).toBe('unsupported');
  });
}

test('characterize optional Bangumi data without claiming lossless malformed-field admission', () => {
  const base = { id: 1014, name: 'Exact', type: 2 };
  const empty = convertBangumiSubject('1014', { ...base, summary: '', tags: [] });
  expect(empty.values.fields[0]!.value).toBe('');
  expect(empty.values.children[0]!.values).toEqual([]);
  const omitted = convertBangumiSubject('1014', base);
  expect(omitted.values.fields).toEqual([]);
  expect(omitted.values.children[0]!.values).toBeNull();
  const malformed = convertBangumiSubject('1014', { ...base, summary: ['text'], tags: [{ name: 'A' }, { name: 12 }] });
  expect(malformed.values.fields).toEqual([]);
  expect(malformed.values.children[0]!.values).toBeNull();
  console.info('malformed optional Bangumi fields', JSON.stringify(malformed));
  expect(() => convertBangumiSubject('1014', { ...base, type: 5 })).toThrow(ProviderConversionError);
  const coercion = convertProviderRecord(identity, { id: ['v11'], name: { value: 'Title' }, olang: ['ja', 'en'] });
  console.info('VNDB unknown-field coercion', JSON.stringify(coercion));
  expect(coercion.data).toEqual({ id: ['v11'], name: { value: 'Title' }, olang: ['ja', 'en'] });
});
